const res = $input.first().json;
const body = res.body || res;
const result = body.result || {};
const summary = `LeadFlow tick OK — drafts generated: ${result.draftsGenerated ?? 0}, sent: ${result.sent ?? 0}, blocked: ${result.blocked ?? 0}, failed: ${result.failed ?? 0}`;
console.log(summary);
return [{ json: { status: 'success', summary, statusCode: res.statusCode ?? 200, result, executedAt: new Date().toISOString() } }];

const err = $input.first().json;
const message = err.error?.message || err.message || JSON.stringify(err);
const summary = `LeadFlow tick FAILED — ${message}. No retry was attempted; LeadFlow's own idempotent state means the next scheduled run will safely pick up any unsent work without duplicating anything already sent.`;
console.error(summary);
return [{ json: { status: 'failure', summary, error: message, executedAt: new Date().toISOString() } }];
